ALTER TABLE "admin_actions" ADD CONSTRAINT "admin_actions_actor_user_id_fkey" FOREIGN KEY ("actor_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ============================================================================
-- Part 2: integrity rules Prisma cannot express
-- ============================================================================

-- Shared guard: permanent financial records are never deleted ----------------
CREATE OR REPLACE FUNCTION prevent_financial_record_delete()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '% rows are permanent financial records and cannot be deleted', TG_TABLE_NAME
        USING ERRCODE = 'restrict_violation';
END;
$$;

-- bookings (payment-scoped M5 subset) -----------------------------------------
ALTER TABLE "bookings"
    ADD CONSTRAINT "bookings_external_ref_format" CHECK (external_ref ~ '^[A-Za-z0-9_.:-]{1,100}$'),
    ADD CONSTRAINT "bookings_vehicle_category_format"
        CHECK (vehicle_category IS NULL OR vehicle_category ~ '^[A-Z][A-Z0-9_]{0,49}$'),
    ADD CONSTRAINT "bookings_fare_positive" CHECK (fare_estimate_minor > 0),
    -- V1 rule: the customer pays exactly the fare confirmed at booking time. No dynamic fares.
    ADD CONSTRAINT "bookings_final_fare_is_confirmed_fare" CHECK (final_fare_minor = fare_estimate_minor),
    ADD CONSTRAINT "bookings_completed_has_timestamp" CHECK (status <> 'COMPLETED' OR completed_at IS NOT NULL),
    ADD CONSTRAINT "bookings_cancelled_has_timestamp" CHECK (status <> 'CANCELLED' OR cancelled_at IS NOT NULL),
    -- M6 payment gate: a booking only completes once it has been paid.
    ADD CONSTRAINT "bookings_completed_is_paid" CHECK (status <> 'COMPLETED' OR payment_status <> 'UNPAID');

CREATE OR REPLACE FUNCTION guard_booking_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.external_ref <> OLD.external_ref
       OR NEW.customer_id <> OLD.customer_id
       OR NEW.vehicle_category IS DISTINCT FROM OLD.vehicle_category
       OR NEW.fare_estimate_minor <> OLD.fare_estimate_minor
       OR NEW.final_fare_minor <> OLD.final_fare_minor
       OR NEW.payment_method <> OLD.payment_method
       OR NEW.fee_rule_id <> OLD.fee_rule_id
       OR NEW.confirmed_at <> OLD.confirmed_at
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Confirmed booking terms (customer, fare, payment method, fee rule) are immutable'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'CREATED' AND NEW.status IN ('SEARCHING_DRIVER', 'DRIVER_ASSIGNED', 'CANCELLED'))
        OR (OLD.status = 'SEARCHING_DRIVER' AND NEW.status IN ('DRIVER_ASSIGNED', 'CANCELLED'))
        OR (OLD.status = 'DRIVER_ASSIGNED' AND NEW.status IN ('COMPLETED', 'CANCELLED'))
    ) THEN
        RAISE EXCEPTION 'Invalid booking transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.payment_status <> OLD.payment_status AND NOT (
           (OLD.payment_status = 'UNPAID' AND NEW.payment_status = 'PAID')
        OR (OLD.payment_status = 'PAID' AND NEW.payment_status = 'REFUND_PENDING')
        OR (OLD.payment_status = 'REFUND_PENDING' AND NEW.payment_status = 'REFUNDED')
    ) THEN
        RAISE EXCEPTION 'Invalid booking payment transition % -> %', OLD.payment_status, NEW.payment_status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_bookings_guard
BEFORE UPDATE ON "bookings"
FOR EACH ROW
EXECUTE FUNCTION guard_booking_update();

-- trips (payment-scoped M6 subset) --------------------------------------------
ALTER TABLE "trips"
    ADD CONSTRAINT "trips_payment_confirmed_has_timestamp"
        CHECK (status NOT IN ('PAYMENT_CONFIRMED', 'COMPLETED') OR payment_confirmed_at IS NOT NULL),
    ADD CONSTRAINT "trips_completed_has_timestamp" CHECK (status <> 'COMPLETED' OR completed_at IS NOT NULL),
    ADD CONSTRAINT "trips_cancelled_has_timestamp" CHECK (status <> 'CANCELLED' OR cancelled_at IS NOT NULL);

-- M6: the backend owns the trip state machine. Transitions follow the documented order
-- (D-03 option A), CANCELLED is reachable from any non-final state (D-02), and
-- PAYMENT_CONFIRMED requires a paid booking (M6 payment gate).
CREATE OR REPLACE FUNCTION guard_trip_change()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'DRIVER_ASSIGNED' THEN
            RAISE EXCEPTION 'A trip starts at DRIVER_ASSIGNED' USING ERRCODE = 'restrict_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id OR NEW.booking_id <> OLD.booking_id OR NEW.driver_id <> OLD.driver_id
       OR NEW.assigned_at <> OLD.assigned_at OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Trip booking, driver and assignment are immutable'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (NEW.status = 'CANCELLED' AND OLD.status NOT IN ('COMPLETED', 'CANCELLED'))
        OR (OLD.status = 'DRIVER_ASSIGNED' AND NEW.status = 'DRIVER_ARRIVED')
        OR (OLD.status = 'DRIVER_ARRIVED' AND NEW.status = 'PICKUP_VERIFIED')
        OR (OLD.status = 'PICKUP_VERIFIED' AND NEW.status = 'IN_TRANSIT')
        OR (OLD.status = 'IN_TRANSIT' AND NEW.status = 'DROP_PROGRESS')
        OR (OLD.status = 'DROP_PROGRESS' AND NEW.status = 'DELIVERED')
        OR (OLD.status = 'DELIVERED' AND NEW.status = 'PAYMENT_CONFIRMED')
        OR (OLD.status = 'PAYMENT_CONFIRMED' AND NEW.status = 'COMPLETED')
    ) THEN
        RAISE EXCEPTION 'Invalid trip transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status = 'PAYMENT_CONFIRMED' AND OLD.status <> 'PAYMENT_CONFIRMED' AND NOT EXISTS (
        SELECT 1 FROM bookings b WHERE b.id = NEW.booking_id AND b.payment_status <> 'UNPAID'
    ) THEN
        RAISE EXCEPTION 'Trip payment cannot be confirmed for an unpaid booking'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_trips_guard
BEFORE INSERT OR UPDATE ON "trips"
FOR EACH ROW
EXECUTE FUNCTION guard_trip_change();

-- fee_rules (PW 1.6) ----------------------------------------------------------
ALTER TABLE "fee_rules"
    ADD CONSTRAINT "fee_rules_rule_type_valid" CHECK (rule_type IN ('FIXED', 'PERCENTAGE')),
    ADD CONSTRAINT "fee_rules_rounding_mode_valid" CHECK (rounding_mode IN ('HALF_UP', 'DOWN', 'UP')),
    ADD CONSTRAINT "fee_rules_value_nonnegative" CHECK (value >= 0),
    -- A percentage fee must leave the driver a share; a fixed fee is a whole number of paise.
    ADD CONSTRAINT "fee_rules_percentage_below_100" CHECK (rule_type <> 'PERCENTAGE' OR value < 100),
    ADD CONSTRAINT "fee_rules_fixed_whole_paise" CHECK (rule_type <> 'FIXED' OR value = trunc(value)),
    ADD CONSTRAINT "fee_rules_window_valid" CHECK (effective_to IS NULL OR effective_to > effective_from),
    ADD CONSTRAINT "fee_rules_category_format" CHECK (category IS NULL OR category ~ '^[A-Z][A-Z0-9_]{0,49}$'),
    ADD CONSTRAINT "fee_rules_reason_not_blank" CHECK (length(btrim(reason)) > 0),
    ADD CONSTRAINT "fee_rules_deactivation_audit"
        CHECK (active OR (deactivated_at IS NOT NULL AND deactivation_reason IS NOT NULL
                          AND length(btrim(deactivation_reason)) > 0));

-- PW: historical fee rules are never overwritten. Only the closing fields may change, once.
CREATE OR REPLACE FUNCTION guard_fee_rule_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.category IS DISTINCT FROM OLD.category
       OR NEW.rule_type <> OLD.rule_type
       OR NEW.value <> OLD.value
       OR NEW.rounding_mode <> OLD.rounding_mode
       OR NEW.effective_from <> OLD.effective_from
       OR NEW.reason <> OLD.reason
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Fee rules are versioned, never edited; create a new rule instead'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.effective_to IS NOT NULL AND NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
        RAISE EXCEPTION 'A closed fee rule cannot be reopened or moved'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NOT OLD.active AND (NEW.active
                           OR NEW.deactivated_at IS DISTINCT FROM OLD.deactivated_at
                           OR NEW.deactivated_by_user_id IS DISTINCT FROM OLD.deactivated_by_user_id
                           OR NEW.deactivation_reason IS DISTINCT FROM OLD.deactivation_reason) THEN
        RAISE EXCEPTION 'A deactivated fee rule cannot be changed'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_fee_rules_versioned
BEFORE UPDATE ON "fee_rules"
FOR EACH ROW
EXECUTE FUNCTION guard_fee_rule_update();

CREATE TRIGGER trg_fee_rules_no_delete
BEFORE DELETE ON "fee_rules"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_fee_rules_no_truncate
BEFORE TRUNCATE ON "fee_rules"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- payment_collections (PW 1.5) ------------------------------------------------
ALTER TABLE "payment_collections"
    ADD CONSTRAINT "collections_stage_valid" CHECK (stage IN ('PICKUP', 'DELIVERY')),
    ADD CONSTRAINT "collections_method_valid" CHECK (method IN ('CASH', 'ONLINE_QR')),
    ADD CONSTRAINT "collections_status_valid" CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),
    ADD CONSTRAINT "collections_amount_positive" CHECK (amount_paise > 0),
    ADD CONSTRAINT "collections_idempotency_key_not_blank" CHECK (length(btrim(idempotency_key)) > 0),
    -- Cash is recorded once the driver holds it, together with its fee and ledger debit.
    ADD CONSTRAINT "collections_cash_shape" CHECK (
        method <> 'CASH' OR (
            status IN ('COMPLETED', 'REVERSED')
            AND provider IS NULL AND provider_product IS NULL AND provider_reference_id IS NULL
            AND provider_payment_id IS NULL
            AND platform_fee_paise IS NOT NULL AND fee_rule_id IS NOT NULL
            AND (platform_fee_paise = 0) = (wallet_transaction_id IS NULL)
        )),
    -- Online collections always reference a provider-issued, booking-linked object (PW 6),
    -- never a personal UPI id. Their fee is taken from the payout, not the wallet.
    ADD CONSTRAINT "collections_online_shape" CHECK (
        method <> 'ONLINE_QR' OR (
            provider IS NOT NULL
            AND provider_product IN ('PAYMENT_LINK', 'QR_CODE')
            AND provider_reference_id IS NOT NULL
            AND platform_fee_paise IS NULL AND wallet_transaction_id IS NULL
        )),
    ADD CONSTRAINT "collections_fee_within_amount"
        CHECK (platform_fee_paise IS NULL OR (platform_fee_paise >= 0 AND platform_fee_paise <= amount_paise)),
    ADD CONSTRAINT "collections_completed_has_refs"
        CHECK (status <> 'COMPLETED' OR (completed_at IS NOT NULL AND (method = 'CASH' OR provider_payment_id IS NOT NULL))),
    ADD CONSTRAINT "collections_failed_has_reason" CHECK (status <> 'FAILED' OR failure_reason IS NOT NULL);

CREATE OR REPLACE FUNCTION guard_collection_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.booking_id <> OLD.booking_id
       OR NEW.trip_id <> OLD.trip_id
       OR NEW.stage <> OLD.stage
       OR NEW.method <> OLD.method
       OR NEW.amount_paise <> OLD.amount_paise
       OR NEW.collected_by_driver_id <> OLD.collected_by_driver_id
       OR NEW.idempotency_key <> OLD.idempotency_key
       OR NEW.provider IS DISTINCT FROM OLD.provider
       OR NEW.provider_product IS DISTINCT FROM OLD.provider_product
       OR NEW.provider_reference_id IS DISTINCT FROM OLD.provider_reference_id
       OR NEW.platform_fee_paise IS DISTINCT FROM OLD.platform_fee_paise
       OR NEW.fee_rule_id IS DISTINCT FROM OLD.fee_rule_id
       OR NEW.wallet_transaction_id IS DISTINCT FROM OLD.wallet_transaction_id
       OR NEW.created_at <> OLD.created_at
       OR (OLD.provider_payment_id IS NOT NULL
           AND NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id) THEN
        RAISE EXCEPTION 'Collection amounts and references are immutable'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'PENDING' AND NEW.status IN ('COMPLETED', 'FAILED'))
        OR (OLD.status = 'COMPLETED' AND NEW.status = 'REVERSED')
    ) THEN
        RAISE EXCEPTION 'Invalid collection transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_collections_guard
BEFORE UPDATE ON "payment_collections"
FOR EACH ROW
EXECUTE FUNCTION guard_collection_update();

CREATE TRIGGER trg_collections_no_delete
BEFORE DELETE ON "payment_collections"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_collections_no_truncate
BEFORE TRUNCATE ON "payment_collections"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- driver_earnings -------------------------------------------------------------
ALTER TABLE "driver_earnings"
    ADD CONSTRAINT "earnings_gross_positive" CHECK (gross_amount_paise > 0),
    ADD CONSTRAINT "earnings_fee_within_gross"
        CHECK (platform_fee_paise >= 0 AND platform_fee_paise <= gross_amount_paise),
    ADD CONSTRAINT "earnings_net_is_gross_minus_fee"
        CHECK (net_amount_paise = gross_amount_paise - platform_fee_paise),
    ADD CONSTRAINT "earnings_single_source" CHECK ((payment_id IS NULL) <> (collection_id IS NULL)),
    -- Cash earnings are settled when the driver takes the cash; they are never payable.
    ADD CONSTRAINT "earnings_cash_is_settled" CHECK ((settlement = 'CASH') = (status = 'SETTLED_IN_CASH')),
    ADD CONSTRAINT "earnings_cash_from_collection" CHECK (settlement <> 'CASH' OR collection_id IS NOT NULL),
    ADD CONSTRAINT "earnings_online_has_payable_at" CHECK (settlement <> 'ONLINE' OR payable_at IS NOT NULL),
    ADD CONSTRAINT "earnings_hold_has_reason"
        CHECK (status <> 'ON_HOLD' OR (hold_reason IS NOT NULL AND length(btrim(hold_reason)) > 0 AND held_at IS NOT NULL)),
    ADD CONSTRAINT "earnings_paid_has_timestamp" CHECK (status <> 'PAID' OR paid_at IS NOT NULL);

-- Amounts are immutable, and the status can only move along the payout lifecycle. The checks
-- against payout_items keep an earning and its payout items in step, so an earning that was
-- paid out can never become payable again.
CREATE OR REPLACE FUNCTION guard_earning_change()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.settlement = 'ONLINE' AND NEW.status NOT IN ('PAYABLE', 'ON_HOLD') THEN
            RAISE EXCEPTION 'An online earning starts PAYABLE or ON_HOLD'
                USING ERRCODE = 'restrict_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.booking_id <> OLD.booking_id
       OR NEW.trip_id <> OLD.trip_id
       OR NEW.driver_id <> OLD.driver_id
       OR NEW.settlement <> OLD.settlement
       OR NEW.gross_amount_paise <> OLD.gross_amount_paise
       OR NEW.platform_fee_paise <> OLD.platform_fee_paise
       OR NEW.net_amount_paise <> OLD.net_amount_paise
       OR NEW.fee_rule_id <> OLD.fee_rule_id
       OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
       OR NEW.collection_id IS DISTINCT FROM OLD.collection_id
       OR NEW.payable_at IS DISTINCT FROM OLD.payable_at
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Earning amounts and sources are immutable'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;
    IF NOT (
           (OLD.status = 'PAYABLE' AND NEW.status IN ('ON_HOLD', 'IN_PAYOUT'))
        OR (OLD.status = 'ON_HOLD' AND NEW.status = 'PAYABLE')
        OR (OLD.status = 'IN_PAYOUT' AND NEW.status IN ('PAID', 'PAYABLE', 'ON_HOLD'))
        OR (OLD.status = 'PAID' AND NEW.status = 'ON_HOLD')
    ) THEN
        RAISE EXCEPTION 'Invalid earning transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status = 'IN_PAYOUT' AND NOT EXISTS (
        SELECT 1 FROM payout_items i WHERE i.earning_id = NEW.id AND i.status = 'INCLUDED'
    ) THEN
        RAISE EXCEPTION 'An earning moves to IN_PAYOUT only with an included payout item'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status = 'PAID' AND NOT EXISTS (
        SELECT 1 FROM payout_items i WHERE i.earning_id = NEW.id AND i.status = 'PAID'
    ) THEN
        RAISE EXCEPTION 'An earning is PAID only through a paid payout item'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status IN ('PAYABLE', 'ON_HOLD') AND EXISTS (
        SELECT 1 FROM payout_items i WHERE i.earning_id = NEW.id AND i.status IN ('INCLUDED', 'PAID')
    ) THEN
        RAISE EXCEPTION 'Earning % is still carried by a payout', NEW.id
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_earnings_guard
BEFORE INSERT OR UPDATE ON "driver_earnings"
FOR EACH ROW
EXECUTE FUNCTION guard_earning_change();

CREATE TRIGGER trg_earnings_no_delete
BEFORE DELETE ON "driver_earnings"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_earnings_no_truncate
BEFORE TRUNCATE ON "driver_earnings"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- driver_bank_accounts --------------------------------------------------------
ALTER TABLE "driver_bank_accounts"
    ADD CONSTRAINT "bank_accounts_ifsc_format" CHECK (ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
    ADD CONSTRAINT "bank_accounts_last4_format" CHECK (account_number_last4 ~ '^[0-9]{4}$'),
    ADD CONSTRAINT "bank_accounts_holder_not_blank" CHECK (length(btrim(account_holder_name)) > 0),
    ADD CONSTRAINT "bank_accounts_verified_audit"
        CHECK (status <> 'VERIFIED' OR (verified_at IS NOT NULL AND verified_by_user_id IS NOT NULL
                                        AND verification_reference IS NOT NULL
                                        AND length(btrim(verification_reference)) > 0)),
    ADD CONSTRAINT "bank_accounts_closed_has_reason"
        CHECK (status NOT IN ('REJECTED', 'DISABLED')
               OR (status_reason IS NOT NULL AND length(btrim(status_reason)) > 0));

CREATE OR REPLACE FUNCTION guard_bank_account_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.driver_id <> OLD.driver_id
       OR NEW.account_holder_name <> OLD.account_holder_name
       OR NEW.ifsc <> OLD.ifsc
       OR NEW.account_number_last4 <> OLD.account_number_last4
       OR NEW.provider <> OLD.provider
       OR NEW.provider_contact_id <> OLD.provider_contact_id
       OR NEW.provider_fund_account_id <> OLD.provider_fund_account_id
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Bank account details are immutable; add a new account instead'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'PENDING_VERIFICATION' AND NEW.status IN ('VERIFIED', 'REJECTED', 'DISABLED'))
        OR (OLD.status = 'VERIFIED' AND NEW.status = 'DISABLED')
    ) THEN
        RAISE EXCEPTION 'Invalid bank account transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_bank_accounts_guard
BEFORE UPDATE ON "driver_bank_accounts"
FOR EACH ROW
EXECUTE FUNCTION guard_bank_account_update();

CREATE TRIGGER trg_bank_accounts_no_delete
BEFORE DELETE ON "driver_bank_accounts"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_bank_accounts_no_truncate
BEFORE TRUNCATE ON "driver_bank_accounts"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- payout_batches --------------------------------------------------------------
ALTER TABLE "payout_batches"
    ADD CONSTRAINT "payout_batches_origin_valid" CHECK (origin IN ('SCHEDULE', 'ADMIN')),
    ADD CONSTRAINT "payout_batches_admin_audit" CHECK (origin <> 'ADMIN' OR created_by_user_id IS NOT NULL),
    ADD CONSTRAINT "payout_batches_cycle_key_format" CHECK (cycle_key ~ '^[0-9]{4}-W[0-9]{2}$'),
    ADD CONSTRAINT "payout_batches_totals_nonnegative" CHECK (payout_count >= 0 AND total_amount_paise >= 0),
    ADD CONSTRAINT "payout_batches_idempotency_key_not_blank" CHECK (length(btrim(idempotency_key)) > 0),
    ADD CONSTRAINT "payout_batches_completed_has_timestamp" CHECK (status <> 'COMPLETED' OR completed_at IS NOT NULL);

CREATE OR REPLACE FUNCTION guard_payout_batch_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.idempotency_key <> OLD.idempotency_key
       OR NEW.cycle_key <> OLD.cycle_key
       OR NEW.origin <> OLD.origin
       OR NEW.cutoff_at <> OLD.cutoff_at
       OR NEW.payout_count <> OLD.payout_count
       OR NEW.total_amount_paise <> OLD.total_amount_paise
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'A prepared payout batch is immutable' USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'PREPARED' AND NEW.status IN ('EXECUTING', 'COMPLETED'))
        OR (OLD.status = 'EXECUTING' AND NEW.status = 'COMPLETED')
    ) THEN
        RAISE EXCEPTION 'Invalid payout batch transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payout_batches_guard
BEFORE UPDATE ON "payout_batches"
FOR EACH ROW
EXECUTE FUNCTION guard_payout_batch_update();

CREATE TRIGGER trg_payout_batches_no_delete
BEFORE DELETE ON "payout_batches"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_payout_batches_no_truncate
BEFORE TRUNCATE ON "payout_batches"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- driver_payouts --------------------------------------------------------------
ALTER TABLE "driver_payouts"
    -- Razorpay's minimum payout is Rs 1.
    ADD CONSTRAINT "payouts_amount_minimum" CHECK (amount_paise >= 100),
    ADD CONSTRAINT "payouts_currency_inr" CHECK (currency = 'INR'),
    ADD CONSTRAINT "payouts_mode_valid" CHECK (mode IN ('IMPS', 'NEFT', 'RTGS')),
    ADD CONSTRAINT "payouts_attempts_nonnegative" CHECK (attempts >= 0),
    ADD CONSTRAINT "payouts_accepted_has_provider_id"
        CHECK (status NOT IN ('SUBMITTED', 'PROCESSED', 'REVERSED') OR provider_payout_id IS NOT NULL),
    ADD CONSTRAINT "payouts_processed_has_timestamp" CHECK (status <> 'PROCESSED' OR processed_at IS NOT NULL),
    ADD CONSTRAINT "payouts_failed_has_reason"
        CHECK (status <> 'FAILED' OR (failed_at IS NOT NULL AND failure_reason IS NOT NULL)),
    ADD CONSTRAINT "payouts_reversed_has_timestamp" CHECK (status <> 'REVERSED' OR reversed_at IS NOT NULL);

CREATE OR REPLACE FUNCTION guard_payout_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.batch_id <> OLD.batch_id
       OR NEW.driver_id <> OLD.driver_id
       OR NEW.bank_account_id <> OLD.bank_account_id
       OR NEW.amount_paise <> OLD.amount_paise
       OR NEW.currency <> OLD.currency
       OR NEW.mode <> OLD.mode
       OR NEW.provider <> OLD.provider
       OR NEW.created_at <> OLD.created_at
       OR (OLD.provider_payout_id IS NOT NULL
           AND NEW.provider_payout_id IS DISTINCT FROM OLD.provider_payout_id) THEN
        RAISE EXCEPTION 'Payout amount, beneficiary and provider reference are immutable'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'PREPARED' AND NEW.status IN ('SUBMITTING', 'FAILED'))
        OR (OLD.status = 'SUBMITTING' AND NEW.status IN ('SUBMITTED', 'PROCESSED', 'FAILED', 'REVERSED'))
        OR (OLD.status = 'SUBMITTED' AND NEW.status IN ('PROCESSED', 'FAILED', 'REVERSED'))
        OR (OLD.status = 'PROCESSED' AND NEW.status = 'REVERSED')
    ) THEN
        RAISE EXCEPTION 'Invalid payout transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payouts_guard
BEFORE UPDATE ON "driver_payouts"
FOR EACH ROW
EXECUTE FUNCTION guard_payout_update();

CREATE TRIGGER trg_payouts_no_delete
BEFORE DELETE ON "driver_payouts"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_payouts_no_truncate
BEFORE TRUNCATE ON "driver_payouts"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- A payout always carries exactly its items: checked at COMMIT, after the items are inserted.
CREATE OR REPLACE FUNCTION check_payout_matches_items()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    item_total BIGINT;
BEGIN
    SELECT COALESCE(SUM(amount_paise), 0) INTO item_total
    FROM payout_items
    WHERE payout_id = NEW.id;
    IF item_total <> NEW.amount_paise THEN
        RAISE EXCEPTION 'Payout % amount % does not equal its items (%)', NEW.id, NEW.amount_paise, item_total
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_payouts_match_items
AFTER INSERT ON "driver_payouts"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION check_payout_matches_items();

-- payout_items ----------------------------------------------------------------
ALTER TABLE "payout_items"
    ADD CONSTRAINT "payout_items_amount_positive" CHECK (amount_paise > 0);

-- An item carries exactly one ONLINE earning of the payout's driver, for its full net amount.
CREATE OR REPLACE FUNCTION guard_payout_item_change()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'INCLUDED' THEN
            RAISE EXCEPTION 'A payout item starts INCLUDED' USING ERRCODE = 'restrict_violation';
        END IF;
        IF NOT EXISTS (
            SELECT 1
            FROM driver_earnings e
            JOIN driver_payouts p ON p.id = NEW.payout_id
            WHERE e.id = NEW.earning_id
              AND e.settlement = 'ONLINE'
              AND e.driver_id = p.driver_id
              AND e.net_amount_paise = NEW.amount_paise
        ) THEN
            RAISE EXCEPTION 'Payout item must carry the full net amount of one of the driver''s online earnings'
                USING ERRCODE = 'restrict_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id OR NEW.payout_id <> OLD.payout_id OR NEW.earning_id <> OLD.earning_id
       OR NEW.amount_paise <> OLD.amount_paise OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'Payout items are immutable' USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'INCLUDED' AND NEW.status IN ('PAID', 'RELEASED', 'REVERSED'))
        OR (OLD.status = 'PAID' AND NEW.status = 'REVERSED')
    ) THEN
        RAISE EXCEPTION 'Invalid payout item transition % -> %', OLD.status, NEW.status
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payout_items_guard
BEFORE INSERT OR UPDATE ON "payout_items"
FOR EACH ROW
EXECUTE FUNCTION guard_payout_item_change();

CREATE TRIGGER trg_payout_items_no_delete
BEFORE DELETE ON "payout_items"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_payout_items_no_truncate
BEFORE TRUNCATE ON "payout_items"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- payout_events ---------------------------------------------------------------
ALTER TABLE "payout_events"
    ADD CONSTRAINT "payout_events_only_verified" CHECK (signature_valid),
    ADD CONSTRAINT "payout_events_attempts_nonnegative" CHECK (attempts >= 0);

-- Documentation for anyone reading the database directly ---------------------
COMMENT ON TABLE "customers" IS 'Customer profile linked to a user (M5). Minimal until M2 is supplied.';
COMMENT ON TABLE "bookings" IS 'Payment-scoped M5 booking registered by the trip engine at confirmation. Fare, method and fee rule are immutable (trigger).';
COMMENT ON COLUMN "bookings"."fare_estimate_minor" IS 'Confirmed fare in paise shown to the customer at booking confirmation.';
COMMENT ON COLUMN "bookings"."final_fare_minor" IS 'Amount the customer pays, in paise. V1: always equals fare_estimate_minor (CHECK).';
COMMENT ON TABLE "trips" IS 'Payment-scoped M6 trip: one per booking, created at assignment. Transitions are enforced by trigger.';
COMMENT ON TABLE "fee_rules" IS 'Versioned platform-fee rules (PW 1.6). Never edited or deleted; bookings pin the rule in effect at confirmation.';
COMMENT ON TABLE "payment_collections" IS 'Pickup/delivery collections (PW 1.5): cash recorded by the driver, or a booking-linked Razorpay payment link / QR code.';
COMMENT ON TABLE "driver_earnings" IS 'Per-trip driver earning: gross fare, platform fee, net share. Separate from the wallet. Amounts immutable (trigger).';
COMMENT ON COLUMN "driver_earnings"."net_amount_paise" IS 'gross - fee. ONLINE: owed to the driver through a weekly payout. CASH: already kept by the driver.';
COMMENT ON TABLE "driver_bank_accounts" IS 'Payout beneficiary. Stores only the last 4 digits of the account number; the provider holds the full details.';
COMMENT ON TABLE "payout_batches" IS 'One weekly (or admin-triggered) payout run.';
COMMENT ON TABLE "driver_payouts" IS 'One bank transfer per driver per batch. id is the provider idempotency key and reference_id.';
COMMENT ON TABLE "payout_items" IS 'Earnings carried by a payout. An earning is INCLUDED or PAID in at most one payout (partial unique index).';
COMMENT ON TABLE "payout_events" IS 'Signature-verified payout-provider webhook events. event_id is the idempotency guard.';
COMMENT ON COLUMN "payout_events"."payload" IS 'Raw provider payload. May contain beneficiary details; access must be restricted.';

-- payment_disputes ------------------------------------------------------------
ALTER TABLE "payment_disputes"
    ADD CONSTRAINT "disputes_amount_nonnegative" CHECK (amount_paise >= 0),
    ADD CONSTRAINT "disputes_status_not_blank" CHECK (length(btrim(status)) > 0);

CREATE TRIGGER trg_disputes_no_delete
BEFORE DELETE ON "payment_disputes"
FOR EACH ROW
EXECUTE FUNCTION prevent_financial_record_delete();

CREATE TRIGGER trg_disputes_no_truncate
BEFORE TRUNCATE ON "payment_disputes"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_financial_record_delete();

-- admin_actions (M1): append-only audit trail --------------------------------
ALTER TABLE "admin_actions"
    ADD CONSTRAINT "admin_actions_action_format" CHECK (action ~ '^[A-Z][A-Z0-9_]{1,59}$'),
    ADD CONSTRAINT "admin_actions_target_not_blank"
        CHECK (length(btrim(target_type)) > 0 AND length(btrim(target_id)) > 0),
    ADD CONSTRAINT "admin_actions_details_object" CHECK (jsonb_typeof(details) = 'object');

CREATE OR REPLACE FUNCTION prevent_admin_action_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'admin_actions is append-only'
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER trg_admin_actions_immutable
BEFORE UPDATE OR DELETE ON "admin_actions"
FOR EACH ROW
EXECUTE FUNCTION prevent_admin_action_mutation();

CREATE TRIGGER trg_admin_actions_no_truncate
BEFORE TRUNCATE ON "admin_actions"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_admin_action_mutation();

COMMENT ON TABLE "payment_disputes" IS 'Razorpay disputes on customer payments. The related earning is held until an admin decides.';
COMMENT ON TABLE "admin_actions" IS 'Append-only audit of admin and ops actions on financial records (M1). UPDATE, DELETE and TRUNCATE are blocked.';
